const s={move:{p:.63,n:66,agreement:63,date:"2026-09-30",source:"the scripted set (test/fixtures/fast-path-commands.json, 197 synthetic Acme commands) through the real Jev (jev-1.13.0) on 2026-09-30, rerun for phase 7: move reaches 95% on 30 at p >= 0.63 (66 kept, 63 agreed, 95.5%). Phase 6 (2026-09-23) read p >= 0.60 off its own run and did not keep n; on this rerun 0.60 kept 70 at 94.3%, under the bar, so the stricter of the two measurements is the one that acts"}},r=Object.fromEntries(Object.entries(s).map(([e,t])=>[e,t.p]));export{s as MEASURED,r as THRESHOLDS};
